-- Keep the historic column and every saved document intact while sharing the
-- structured computer model between PCs and laptops.
alter table public.equipment
  drop constraint equipment_pc_configuration_type,
  drop constraint equipment_pc_configuration_shape,
  add constraint equipment_pc_configuration_type check (
    pc_configuration is null or equipment_type in ('pc', 'laptop')
  ),
  add constraint equipment_pc_configuration_pc_components check (
    pc_configuration is null
    or equipment_type = 'pc'
    or (
      coalesce(pc_configuration -> 'motherboard', 'null'::jsonb) = 'null'::jsonb
      and coalesce(pc_configuration -> 'powerSupply', 'null'::jsonb) = 'null'::jsonb
    )
  ),
  add constraint equipment_pc_configuration_shape check (
    pc_configuration is null or extensions.jsonb_matches_schema(
      $schema${"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"processor":{"anyOf":[{"oneOf":[{"type":"object","properties":{"manufacturer":{"type":"string","const":"AMD"},"family":{"anyOf":[{"type":"string","enum":["Ryzen 3","Ryzen 5","Ryzen 7","Ryzen 9","Threadripper","Other"]},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]}},"required":["manufacturer","family","model"],"additionalProperties":false},{"type":"object","properties":{"manufacturer":{"type":"string","const":"Intel"},"family":{"anyOf":[{"type":"string","enum":["Core i3","Core i5","Core i7","Core i9","Core Ultra 5","Core Ultra 7","Core Ultra 9","Xeon","Other"]},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]}},"required":["manufacturer","family","model"],"additionalProperties":false}]},{"type":"null"}]},"graphics":{"anyOf":[{"oneOf":[{"type":"object","properties":{"mode":{"type":"string","const":"integrated"}},"required":["mode"],"additionalProperties":false},{"type":"object","properties":{"mode":{"type":"string","const":"discrete"},"details":{"oneOf":[{"type":"object","properties":{"vendor":{"type":"string","const":"NVIDIA"},"family":{"anyOf":[{"type":"string","enum":["GeForce GTX","GeForce RTX","Professional","Other"]},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"vramGb":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]}},"required":["vendor","family","model","vramGb"],"additionalProperties":false},{"type":"object","properties":{"vendor":{"type":"string","const":"AMD"},"family":{"anyOf":[{"type":"string","enum":["Radeon RX","Radeon Pro","Other"]},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"vramGb":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]}},"required":["vendor","family","model","vramGb"],"additionalProperties":false},{"type":"object","properties":{"vendor":{"type":"string","const":"Intel"},"family":{"anyOf":[{"type":"string","enum":["Arc","Other"]},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"vramGb":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]}},"required":["vendor","family","model","vramGb"],"additionalProperties":false},{"type":"object","properties":{"vendor":{"type":"string","const":"Other"},"family":{"anyOf":[{"type":"string","enum":["Other"]},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"vramGb":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]}},"required":["vendor","family","model","vramGb"],"additionalProperties":false}]}},"required":["mode","details"],"additionalProperties":false}]},{"type":"null"}]},"memory":{"type":"object","properties":{"capacityGb":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]},"generation":{"anyOf":[{"type":"string","enum":["DDR3","DDR4","DDR5","Other"]},{"type":"null"}]},"moduleCount":{"anyOf":[{"type":"integer","minimum":1,"maximum":128},{"type":"null"}]}},"required":["capacityGb","generation","moduleCount"],"additionalProperties":false},"drives":{"maxItems":32,"type":"array","items":{"type":"object","properties":{"type":{"type":"string","enum":["nvme_ssd","sata_ssd","hdd","other"]},"capacity":{"type":"number","exclusiveMinimum":0,"maximum":1000000},"unit":{"type":"string","enum":["GB","TB"]}},"required":["type","capacity","unit"],"additionalProperties":false}},"motherboard":{"anyOf":[{"type":"object","properties":{"manufacturer":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"chipset":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]}},"required":["manufacturer","model","chipset"],"additionalProperties":false},{"type":"null"}]},"powerSupply":{"anyOf":[{"type":"object","properties":{"manufacturer":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"model":{"anyOf":[{"type":"string","maxLength":160},{"type":"null"}]},"wattage":{"anyOf":[{"type":"integer","exclusiveMinimum":0,"maximum":100000},{"type":"null"}]},"efficiency":{"anyOf":[{"type":"string","enum":["80 PLUS","80 PLUS Bronze","80 PLUS Silver","80 PLUS Gold","80 PLUS Platinum","80 PLUS Titanium","Other"]},{"type":"null"}]}},"required":["manufacturer","model","wattage","efficiency"],"additionalProperties":false},{"type":"null"}]}},"required":["processor","graphics","memory","drives"],"additionalProperties":false}$schema$::json,
      pc_configuration
    )
  );

comment on column public.equipment.pc_configuration is
  'Computer-owned processor, graphics, memory and ordered drives for PCs and laptops, plus optional PC-only motherboard and power supply details. Legacy text columns remain unchanged.';
